import java.util.*;
import java.io.*;

public class Main {
    static final long MOD_A = 998244353;
    static final long MOD_B = 1000000007;
    static long final_result;
    static long total_numbers;
    static long counter2;
    static List<Long>[] digit_buckets = new ArrayList[7];
    static long[] prefix_sums = new long[7];
    static long[] powers_of_ten = {1, 10, 100, 1000, 10000, 100000, 1000000};
    static long count_pairs;

    static {
        for (int i = 0; i < 7; i++) {
            digit_buckets[i] = new ArrayList<>();
        }
    }

    static void generate_buckets(int level, long current) {
        if (level == 7) return;
        long val = (total_numbers - current + MOD_A) % MOD_A;
        digit_buckets[level].add(val);
        prefix_sums[level] += val;
        total_numbers++;
        for (int d = 0; d <= 9; d++) {
            generate_buckets(level + 1, current * 10 + d);
        }
    }

    static boolean check_range(long x) {
        return x * 1000000 + 999999 <= total_numbers && x * 10000000 > total_numbers;
    }

    static void explore(long level, long val) {
        if (val > total_numbers) return;
        if (check_range(val)) {
            for (int i = 0; i <= 6; i++) {
                long offset = ((counter2 + 1 - (val * powers_of_ten[i]) % MOD_A) + MOD_A) % MOD_A;
                List<Long> bucket = digit_buckets[i];
                int pos = lowerBound(bucket, MOD_A - offset);
                long sum_prefix = prefix_sums[i];
                long size = bucket.size();
                long sum_before_pos = 0;
                if (pos > 0) {
                    sum_before_pos = sumOfRange(bucket, 0, pos - 1);
                }
                long sum_after_pos = sumOfRange(bucket, pos, (int) size - 1);
                final_result = (final_result + (sum_prefix + offset * size - MOD_A * (size - pos)) % MOD_B) % MOD_B;
            }
            count_pairs += 1;
        } else {
            count_pairs++;
            final_result = (final_result + ((count_pairs - val) % MOD_A + MOD_A) % MOD_A) % MOD_B;
            for (int d = (! (level > 0) ? 0 : 1); d <= 9; d++) {
                explore(level + 1, val * 10 + d);
            }
        }
    }

    static int lowerBound(List<Long> list, long key) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) / 2;
            if (list.get(mid) >= key) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        return low;
    }

    static long sumOfRange(List<Long> list, int start, int end) {
        long sum = 0;
        for (int i = start; i <= end; i++) {
            sum += list.get(i);
        }
        return sum;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        total_numbers = Long.parseLong(br.readLine().trim());
        generate_buckets(0, 0);
        for (int i = 0; i <= 6; i++) {
